                if distances[next][conseq] > tot_weight {
                    distances[next][conseq] = tot_weight;
                    p_queue.push(Reverse((next, tot_weight, conseq)));
                }
            }
        }

        distances[len - 1]
            .iter()
            .filter(|&&x| x != i32::MAX)
            .min()
            .cloned()
            .unwrap_or(-1)
    }
